```sql
/* Список всех шеф-поваров (executive и sous) в алфавитном порядке */
SELECT "full_name"
FROM (
    SELECT "full_name" FROM "executive_chef"
    UNION
    SELECT "full_name" FROM "sous_chef"
) AS "chefs"
ORDER BY "full_name" ASC;
```

